#!/usr/bin/env bash
# =============================================================================
# Container Registry for Backup Scripts
# =============================================================================
# Central source of truth for container IDs and backup configuration.
# Source this file from other backup scripts.
#
# Usage in scripts:
#   source "$(dirname "$0")/containers.sh"
#   VMID=$(get_container_id "openwebui")
# =============================================================================

# -----------------------------------------------------------------------------
# Backup Tiers
# -----------------------------------------------------------------------------
# Daily: User data that changes frequently (kept 7 days)
# Weekly: Infrastructure that rarely changes (kept 4 weeks)

DAILY_CONTAINERS="304 501 502"      # immich, openwebui, n8n
WEEKLY_CONTAINERS="100 101 200 201 202 401 402 500"  # infrastructure

# All containers to backup (excludes stateless/temporary)
ALL_BACKUP_CONTAINERS="$WEEKLY_CONTAINERS $DAILY_CONTAINERS"

# Excluded from backups (documented here for reference)
# 303 = immich-importer (stateless, runs cron jobs only)
# 600 = desktop-tmp (temporary GUI container)

# -----------------------------------------------------------------------------
# Container ID Lookup
# -----------------------------------------------------------------------------
# Get container ID by app name
# Usage: VMID=$(get_container_id "openwebui")
get_container_id() {
    local app="$1"
    case "$app" in
        portainer)         echo "100" ;;
        network-services)  echo "101" ;;
        traefik)           echo "200" ;;
        dashboards)        echo "201" ;;
        authelia)          echo "202" ;;
        immich)            echo "304" ;;
        jellyfin)          echo "401" ;;
        media-management)  echo "402" ;;
        monitoring)        echo "500" ;;
        openwebui)         echo "501" ;;
        n8n)               echo "502" ;;
        *)                 echo "" ;;
    esac
}

# Get app name by container ID
# Usage: APP=$(get_app_name 501)
get_app_name() {
    local vmid="$1"
    case "$vmid" in
        100) echo "portainer" ;;
        101) echo "network-services" ;;
        200) echo "traefik" ;;
        201) echo "dashboards" ;;
        202) echo "authelia" ;;
        304) echo "immich" ;;
        401) echo "jellyfin" ;;
        402) echo "media-management" ;;
        500) echo "monitoring" ;;
        501) echo "openwebui" ;;
        502) echo "n8n" ;;
        *)   echo "" ;;
    esac
}

# List all app names
# Usage: list_apps
list_apps() {
    echo "portainer network-services traefik dashboards authelia immich jellyfin media-management monitoring openwebui n8n" | tr ' ' '\n' | sort
}

# Check if app exists
# Usage: if app_exists "openwebui"; then ...
app_exists() {
    local app="$1"
    local vmid
    vmid=$(get_container_id "$app")
    [[ -n "$vmid" ]]
}

# Print formatted app list for help messages
print_app_list() {
    echo "Available apps:"
    printf "  %-20s (ID: %s)\n" "authelia" "202"
    printf "  %-20s (ID: %s)\n" "dashboards" "201"
    printf "  %-20s (ID: %s)\n" "immich" "304"
    printf "  %-20s (ID: %s)\n" "jellyfin" "401"
    printf "  %-20s (ID: %s)\n" "media-management" "402"
    printf "  %-20s (ID: %s)\n" "monitoring" "500"
    printf "  %-20s (ID: %s)\n" "n8n" "502"
    printf "  %-20s (ID: %s)\n" "network-services" "101"
    printf "  %-20s (ID: %s)\n" "openwebui" "501"
    printf "  %-20s (ID: %s)\n" "portainer" "100"
    printf "  %-20s (ID: %s)\n" "traefik" "200"
}
